                LocalDate.of(2026, 2, 1), LocalDate.of(2027, 2, 1));
        loanService.confirmHandover(contractId, "RETURN", LoanService.PARTY_MUSEUM);
        loanService.confirmHandover(contractId, "RETURN", LoanService.PARTY_BORROWER);
