    @Test
    void applyRejectsFrozenShowcase() {
        jdbc.update("UPDATE showcase SET frozen = TRUE WHERE id = ?", SHOWCASE_PAPER);
        ApiException ex = assertThrows(ApiException.class, () -> loanService.apply(newRequestId(),
